//! Deterministic native host templates used by `nexa generate`.

use nexa_ir::Permission;

use super::ProjectConfig;

pub(super) fn root_readme(app_name: &str, targets: &[&str]) -> String {
    let mut readme = format!(
        "# {app_name}\n\nGenerated by Nexa from a single `.nx` entry file. Edit the Nexa source and regenerate; generated native files are build outputs. Edit `nexa.config.nx` to customize compile-time permissions, iOS purpose messages, and declared plugin options.\n\n"
    );
    if targets.contains(&"ios") {
        readme.push_str(&format!("## iOS\n\n`xcodebuild -project ios/{app_name}.xcodeproj -scheme {app_name} -sdk iphonesimulator build`\n\nOpen `ios/{app_name}.xcodeproj` in Xcode to run on a device or simulator.\n\n"));
    }
    if targets.contains(&"android") {
        readme.push_str("## Android\n\n`gradle -p android :app:assembleDebug`\n\nThe generated Gradle project uses Jetpack Compose and Coil 3 with the platform network stack when needed. Release builds enable R8 shrinking, resource shrinking, and the optimized Android ruleset.\n\n");
    }
    readme.push_str("Requirements: Rust/Nexa for regeneration, Xcode 27+ for iOS, and Android SDK/Gradle for Android.\n");
    readme
}

pub(super) fn ios_info_plist(app_name: &str, config: &ProjectConfig) -> String {
    let mut entries = String::new();
    for (permission, description) in config.permissions() {
        let keys: &[&str] = match *permission {
            Permission::Camera => &["NSCameraUsageDescription"],
            Permission::Microphone => &["NSMicrophoneUsageDescription"],
            Permission::Photos => &["NSPhotoLibraryUsageDescription"],
            Permission::Location => &["NSLocationWhenInUseUsageDescription"],
            // iOS notification authorization has no Info.plist usage-description key.
            Permission::Notifications => &[],
            Permission::Contacts => &["NSContactsUsageDescription"],
            Permission::Calendar => &["NSCalendarsFullAccessUsageDescription"],
            Permission::Bluetooth => &["NSBluetoothAlwaysUsageDescription"],
        };
        for key in keys {
            entries.push_str(&format!(
                "<key>{key}</key><string>{}</string>",
                xml_escape(description)
            ));
        }
    }
    format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\"><dict><key>CFBundleDisplayName</key><string>{app_name}</string><key>CFBundleIdentifier</key><string>com.nexa.{}</string><key>CFBundleName</key><string>{app_name}</string><key>CFBundlePackageType</key><string>APPL</string><key>CFBundleShortVersionString</key><string>1.0</string><key>CFBundleVersion</key><string>1</string><key>LSRequiresIPhoneOS</key><true/>{entries}</dict></plist>\n",
        app_name.to_ascii_lowercase()
    )
}

fn merge_swift_packages(plugins: &[nexa_ir::Plugin]) -> Result<Vec<nexa_ir::SwiftPackage>, String> {
    let mut packages: Vec<nexa_ir::SwiftPackage> = Vec::new();
    let mut product_owners = std::collections::HashMap::<String, String>::new();
    for plugin in plugins {
        for package in &plugin.swift_packages {
            if let Some(existing) = packages.iter_mut().find(|value| value.url == package.url) {
                if existing.from != package.from {
                    return Err(format!(
                        "Swift package `{}` has conflicting minimum versions `{}` and `{}`",
                        package.url, existing.from, package.from
                    ));
                }
                for product in &package.products {
                    if let Some(owner) = product_owners.get(product)
                        && owner != &package.url
                    {
                        return Err(format!(
                            "Swift package product `{product}` is declared by both `{owner}` and `{}`",
                            package.url
                        ));
                    }
                    product_owners.insert(product.clone(), package.url.clone());
                    if !existing.products.contains(product) {
                        existing.products.push(product.clone());
                    }
                }
            } else {
                for product in &package.products {
                    if let Some(owner) = product_owners.get(product)
                        && owner != &package.url
                    {
                        return Err(format!(
                            "Swift package product `{product}` is declared by both `{owner}` and `{}`",
                            package.url
                        ));
                    }
                    product_owners.insert(product.clone(), package.url.clone());
                }
                packages.push(package.clone());
            }
        }
    }
    Ok(packages)
}

fn render_swift_package_objects(packages: &[nexa_ir::SwiftPackage]) -> String {
    let mut objects = String::new();
    let mut product_index = 0;
    for (package_index, package) in packages.iter().enumerate() {
        objects.push_str(&format!(
            "\n\t\t{} = {{ isa = XCRemoteSwiftPackageReference; repositoryURL = \"{}\"; requirement = {{ kind = upToNextMajorVersion; minimumVersion = \"{}\"; }}; }};",
            pbx_identifier(1000 + package_index),
            package.url,
            package.from
        ));
        for product in &package.products {
            objects.push_str(&format!(
                "\n\t\t{} = {{ isa = XCSwiftPackageProductDependency; package = {}; productName = \"{}\"; }};\n\t\t{} = {{ isa = PBXBuildFile; productRef = {}; }};",
                pbx_identifier(2000 + product_index),
                pbx_identifier(1000 + package_index),
                product,
                pbx_identifier(3000 + product_index),
                pbx_identifier(2000 + product_index)
            ));
            product_index += 1;
        }
    }
    objects
}

fn pbx_identifier(index: usize) -> String {
    format!("BB{:022X}", index)
}

fn minimum_ios_version(plugins: &[nexa_ir::Plugin]) -> Result<String, String> {
    let mut minimum = vec![17_u32, 0];
    for version in plugins
        .iter()
        .filter_map(|plugin| plugin.ios_min_version.as_deref())
    {
        let parts = version
            .split('.')
            .map(str::parse::<u32>)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|_| format!("invalid iOS minimum version `{version}`"))?;
        if parts.len() < 2 || parts.len() > 3 {
            return Err(format!("invalid iOS minimum version `{version}`"));
        }
        let width = minimum.len().max(parts.len());
        let greater = (0..width)
            .map(|index| {
                (
                    *parts.get(index).unwrap_or(&0),
                    *minimum.get(index).unwrap_or(&0),
                )
            })
            .find(|(left, right)| left != right)
            .is_some_and(|(left, right)| left > right);
        if greater {
            minimum = parts;
        }
    }
    let mut formatted = minimum.iter().map(u32::to_string).collect::<Vec<_>>();
    while formatted.len() > 2 && formatted.last().is_some_and(|part| part == "0") {
        formatted.pop();
    }
    Ok(formatted.join("."))
}

fn merge_maven_dependencies(plugins: &[nexa_ir::Plugin]) -> Result<Vec<String>, String> {
    let mut dependencies = Vec::new();
    let mut versions = std::collections::HashMap::<String, String>::new();
    for dependency in plugins
        .iter()
        .flat_map(|plugin| plugin.maven_dependencies.iter())
    {
        let parts = dependency.split(':').collect::<Vec<_>>();
        if parts.len() != 3 {
            return Err(format!("invalid Android Maven dependency `{dependency}`"));
        }
        let artifact = format!("{}:{}", parts[0], parts[1]);
        if let Some(version) = versions.get(&artifact) {
            if version != parts[2] {
                return Err(format!(
                    "Android Maven artifact `{artifact}` has conflicting versions `{version}` and `{}`",
                    parts[2]
                ));
            }
            continue;
        }
        versions.insert(artifact, parts[2].to_owned());
        dependencies.push(dependency.clone());
    }
    Ok(dependencies)
}

pub(super) fn ios_project_file(
    app_name: &str,
    has_assets: bool,
    generated_sources: &[String],
    plugin_sources: &[String],
    plugins: &[nexa_ir::Plugin],
) -> Result<String, String> {
    let packages = merge_swift_packages(plugins)?;
    let product_count = packages
        .iter()
        .map(|package| package.products.len())
        .sum::<usize>();
    let package_reference_ids = (0..packages.len())
        .map(|index| pbx_identifier(1000 + index))
        .collect::<Vec<_>>();
    let package_product_ids = (0..product_count)
        .map(|index| pbx_identifier(2000 + index))
        .collect::<Vec<_>>();
    let package_build_ids = (0..product_count)
        .map(|index| pbx_identifier(3000 + index))
        .collect::<Vec<_>>();
    let package_objects = render_swift_package_objects(&packages);
    let mut project =
        ios_project_base_file(app_name, has_assets, generated_sources, plugin_sources);
    project = project.replace(
        "targets = ( AA0000000000000000000005 );",
        &format!(
            "targets = ( AA0000000000000000000005 ); packageReferences = ( {} );",
            package_reference_ids.join(", ")
        ),
    );
    project = project.replace(
        "productType = \"com.apple.product-type.application\"; };",
        &format!(
            "productType = \"com.apple.product-type.application\"; packageProductDependencies = ( {} ); }};",
            package_product_ids.join(", ")
        ),
    );
    project = project.replace(
        "PBXFrameworksBuildPhase; files = (); };",
        &format!(
            "PBXFrameworksBuildPhase; files = ( {} ); }};",
            package_build_ids.join(", ")
        ),
    );
    if !package_objects.is_empty() {
        let insertion = "\n\t\tAA0000000000000000000005 = { isa = PBXNativeTarget;";
        project = project.replace(insertion, &format!("{package_objects}{insertion}"));
    }
    let minimum_version = minimum_ios_version(plugins)?;
    project = project.replace(
        "IPHONEOS_DEPLOYMENT_TARGET = 17.0",
        &format!("IPHONEOS_DEPLOYMENT_TARGET = {minimum_version}"),
    );
    Ok(project)
}

fn ios_project_base_file(
    app_name: &str,
    has_assets: bool,
    generated_sources: &[String],
    plugin_sources: &[String],
) -> String {
    let app_file = format!("{app_name}App.swift");
    let asset_group = if has_assets {
        ", AA0000000000000000000015"
    } else {
        ""
    };
    let asset_reference = if has_assets {
        "\n\t\tAA0000000000000000000015 = { isa = PBXFileReference; lastKnownFileType = folder.assetcatalog; path = Assets.xcassets; sourceTree = \"<group>\"; };"
    } else {
        ""
    };
    let asset_build_file = if has_assets {
        "\n\t\tAA0000000000000000000023 = { isa = PBXBuildFile; fileRef = AA0000000000000000000015; };"
    } else {
        ""
    };
    let resource_files = if has_assets {
        "AA0000000000000000000023"
    } else {
        ""
    };
    let plugin_group_children = plugin_sources
        .iter()
        .enumerate()
        .map(|(index, _)| format!(", AA00000000000000000000{:02}", 30 + index))
        .collect::<String>();
    let plugin_file_references = plugin_sources
        .iter()
        .enumerate()
        .map(|(index, name)| {
            format!(
                "\n\t\tAA00000000000000000000{:02} = {{ isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = NexaPlugins/{name}; sourceTree = \"<group>\"; }};",
                30 + index
            )
        })
        .collect::<String>();
    let plugin_build_files = plugin_sources
        .iter()
        .enumerate()
        .map(|(index, _)| {
            format!(
                "\n\t\tAA00000000000000000000{:02} = {{ isa = PBXBuildFile; fileRef = AA00000000000000000000{:02}; }};",
                60 + index,
                30 + index
            )
        })
        .collect::<String>();
    let plugin_build_ids = plugin_sources
        .iter()
        .enumerate()
        .map(|(index, _)| format!(", AA00000000000000000000{:02}", 60 + index))
        .collect::<String>();
    let generated_group_children = generated_sources
        .iter()
        .skip(1)
        .enumerate()
        .map(|(index, _)| format!(", AA00000000000000000000{:02}", 40 + index))
        .collect::<String>();
    let generated_file_references = generated_sources
        .iter()
        .skip(1)
        .enumerate()
        .map(|(index, name)| {
            format!(
                "\n\t\tAA00000000000000000000{:02} = {{ isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = {name}; sourceTree = \"<group>\"; }};",
                40 + index
            )
        })
        .collect::<String>();
    let generated_build_files = generated_sources
        .iter()
        .skip(1)
        .enumerate()
        .map(|(index, _)| {
            format!(
                "\n\t\tAA00000000000000000000{:02} = {{ isa = PBXBuildFile; fileRef = AA00000000000000000000{:02}; }};",
                90 + index,
                40 + index
            )
        })
        .collect::<String>();
    let generated_build_ids = generated_sources
        .iter()
        .skip(1)
        .enumerate()
        .map(|(index, _)| format!(", AA00000000000000000000{:02}", 90 + index))
        .collect::<String>();
    format!(
        "// !$*UTF8*$!\n{{\n\tarchiveVersion = 1;\n\tclasses = {{}};\n\tobjectVersion = 77;\n\tobjects = {{\n\t\tAA0000000000000000000001 = {{ isa = PBXProject; buildConfigurationList = AA0000000000000000000002; compatibilityVersion = \"Xcode 16.0\"; mainGroup = AA0000000000000000000003; productRefGroup = AA0000000000000000000004; targets = ( AA0000000000000000000005 ); }};\n\t\tAA0000000000000000000003 = {{ isa = PBXGroup; children = ( AA0000000000000000000014, AA0000000000000000000004 ); sourceTree = \"<group>\"; }};\n\t\tAA0000000000000000000014 = {{ isa = PBXGroup; children = ( AA0000000000000000000010, AA0000000000000000000011, AA0000000000000000000012{asset_group}{generated_group_children}{plugin_group_children} ); path = {app_name}; sourceTree = \"<group>\"; }};{asset_reference}{generated_file_references}{plugin_file_references}\n\t\tAA0000000000000000000004 = {{ isa = PBXGroup; children = ( AA0000000000000000000013 ); name = Products; sourceTree = \"<group>\"; }};\n\t\tAA0000000000000000000010 = {{ isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = {app_file}; sourceTree = \"<group>\"; }};\n\t\tAA0000000000000000000011 = {{ isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = NexaGenerated.swift; sourceTree = \"<group>\"; }};\n\t\tAA0000000000000000000012 = {{ isa = PBXFileReference; lastKnownFileType = text.plist.xml; path = Info.plist; sourceTree = \"<group>\"; }};\n\t\tAA0000000000000000000013 = {{ isa = PBXFileReference; explicitFileType = wrapper.application; includeInIndex = 0; path = {app_name}.app; sourceTree = BUILT_PRODUCTS_DIR; }};\n\t\tAA0000000000000000000020 = {{ isa = PBXBuildFile; fileRef = AA0000000000000000000010; }};\n\t\tAA0000000000000000000021 = {{ isa = PBXBuildFile; fileRef = AA0000000000000000000011; }};{generated_build_files}{asset_build_file}{plugin_build_files}\n\t\tAA0000000000000000000005 = {{ isa = PBXNativeTarget; buildConfigurationList = AA0000000000000000000007; buildPhases = ( AA0000000000000000000008, AA0000000000000000000009, AA000000000000000000000A ); name = {app_name}; productName = {app_name}; productReference = AA0000000000000000000013; productType = \"com.apple.product-type.application\"; }};\n\t\tAA0000000000000000000008 = {{ isa = PBXSourcesBuildPhase; files = ( AA0000000000000000000020, AA0000000000000000000021{generated_build_ids}{plugin_build_ids} ); }};\n\t\tAA0000000000000000000009 = {{ isa = PBXFrameworksBuildPhase; files = (); }};\n\t\tAA000000000000000000000A = {{ isa = PBXResourcesBuildPhase; files = ( {resource_files} ); }};\n\t\tAA0000000000000000000002 = {{ isa = XCConfigurationList; buildConfigurations = ( AA0000000000000000000022 ); defaultConfigurationIsVisible = 0; defaultConfigurationName = Release; }};\n\t\tAA0000000000000000000007 = {{ isa = XCConfigurationList; buildConfigurations = ( AA0000000000000000000023 ); defaultConfigurationIsVisible = 0; defaultConfigurationName = Release; }};\n\t\tAA0000000000000000000022 = {{ isa = XCBuildConfiguration; buildSettings = {{ ALWAYS_SEARCH_USER_PATHS = NO; SWIFT_VERSION = 5.0; SWIFT_OPTIMIZATION_LEVEL = \"-O\"; SWIFT_COMPILATION_MODE = wholemodule; GCC_OPTIMIZATION_LEVEL = s; DEAD_CODE_STRIPPING = YES; IPHONEOS_DEPLOYMENT_TARGET = 16.0; }}; name = Release; }};\n\t\tAA0000000000000000000023 = {{ isa = XCBuildConfiguration; buildSettings = {{ ALWAYS_SEARCH_USER_PATHS = NO; PRODUCT_BUNDLE_IDENTIFIER = com.nexa.{}; PRODUCT_NAME = {app_name}; INFOPLIST_FILE = {app_name}/Info.plist; SUPPORTED_PLATFORMS = \"iphoneos iphonesimulator\"; SWIFT_VERSION = 5.0; SWIFT_OPTIMIZATION_LEVEL = \"-O\"; SWIFT_COMPILATION_MODE = wholemodule; GCC_OPTIMIZATION_LEVEL = s; DEAD_CODE_STRIPPING = YES; IPHONEOS_DEPLOYMENT_TARGET = 16.0; TARGETED_DEVICE_FAMILY = \"1,2\"; }}; name = Release; }};\n\t}};\n\trootObject = AA0000000000000000000001;\n}}\n",
        app_name.to_ascii_lowercase()
    )
    .replace("compatibilityVersion = \"Xcode 16.0\"", "compatibilityVersion = \"Xcode 27.0\"")
    .replace("SWIFT_VERSION = 5.0", "SWIFT_VERSION = 6.0")
    .replace("IPHONEOS_DEPLOYMENT_TARGET = 16.0", "IPHONEOS_DEPLOYMENT_TARGET = 17.0")
}

pub(super) fn ios_scheme(app_name: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<Scheme LastUpgradeVersion="2700" version="1.7">
   <BuildAction parallelizeBuildables="YES" buildImplicitDependencies="YES">
      <BuildActionEntries>
         <BuildActionEntry buildForTesting="YES" buildForRunning="YES" buildForProfiling="YES" buildForArchiving="YES" buildForAnalyzing="YES">
            <BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="AA0000000000000000000005" BuildableName="{app_name}.app" BlueprintName="{app_name}" ReferencedContainer="container:{app_name}.xcodeproj"/>
         </BuildActionEntry>
      </BuildActionEntries>
   </BuildAction>
   <TestAction buildConfiguration="Release" shouldUseLaunchSchemeArgsEnv="YES"/>
   <LaunchAction buildConfiguration="Release" useCustomWorkingDirectory="NO" ignoresPersistentStateOnLaunch="NO" debugDocumentVersioning="YES" debugServiceExtension="internal" allowLocationSimulation="YES">
      <BuildableProductRunnable runnableDebuggingMode="0">
         <BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="AA0000000000000000000005" BuildableName="{app_name}.app" BlueprintName="{app_name}" ReferencedContainer="container:{app_name}.xcodeproj"/>
      </BuildableProductRunnable>
   </LaunchAction>
   <ProfileAction buildConfiguration="Release" shouldUseLaunchSchemeArgsEnv="YES" savedToolIdentifier="" useCustomWorkingDirectory="NO" debugDocumentVersioning="YES">
      <BuildableProductRunnable runnableDebuggingMode="0">
         <BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="AA0000000000000000000005" BuildableName="{app_name}.app" BlueprintName="{app_name}" ReferencedContainer="container:{app_name}.xcodeproj"/>
      </BuildableProductRunnable>
   </ProfileAction>
   <AnalyzeAction buildConfiguration="Release"/>
   <ArchiveAction buildConfiguration="Release" revealArchiveInOrganizer="YES"/>
</Scheme>
"#
    )
}

